#!/usr/bin/env bash
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../../core" && pwd -P)}/hooks/lib/role-directive.sh"
YOU_DECIDE="YOU DECIDE: whether every screen/flow named in the interaction-design record's states section has stated its complete state set — default, empty, error, loading — plus the realized spec's required field names (state_name, node_type, transitions, edge_case_variant) — before the record can be treated as covering that screen/flow."
USE_WHEN="USE_WHEN: phase 2, once the interaction-design record's states/state-coverage heading exists and names screens/flows; this plugin does not judge which states are visually right, only whether the four state words AND the four spec fields (state_name, node_type, transitions, edge_case_variant) are named per screen/flow, that node_type is one of state/choice/terminal, that every transitions entry resolves to a state_name defined in the record, and that at least one node_type: terminal entry exists."
PRODUCES="PRODUCES: a per-write pass/fail on docs/issue-<n>/reports/interaction-design.md — naming exactly which of default/empty/error/loading or state_name/node_type/transitions/edge_case_variant is missing for the screen/flow block in question, or that a transitions reference is unresolvable (loop_state: screen-ref-unresolvable), or that no node_type: terminal entry exists, or that the states heading is a stub, or that no states heading exists at all. For each named state, also require a checked-by clause naming whether that state's correctness is judged by a static presence check (the state is named, its content is non-blank) or requires a walked simulation (e.g. an error-recovery state whose correctness depends on whether the recovery path actually returns the user to a completable task, not only on whether an error message is present) — a state with no checked-by clause is treated the same as a missing state."
HAND_OFF="HAND-OFF: none — this is a phase-2 mechanical gate on top of (never instead of) the umbrella interaction-design record gate; other plugins in the set own their own concerns."
core_role_directive "$YOU_DECIDE" "$USE_WHEN" "$PRODUCES" "$HAND_OFF"
